import { useCallback, useEffect } from 'react'
import { useErrorContextValue } from '../../../globalContextProvider/ErrorContext'
import { performErrorReset } from '../actions'

export const useError = () => {
  const [error, dispatch] = useErrorContextValue()

  useEffect(() => {
  }, [error])
  const resetError = useCallback((keys = []) => {
    dispatch(performErrorReset(keys))
  }, [dispatch])
  return { resetError }
}
