import React, { useEffect } from 'react'
import { Button, Icon } from 'antd'
import { Container } from './index.style'
import CreatePaymentForm from './paymentForm'

const AddParticipantsPayment = ({ history, match, ...props }) => {
  useEffect(() => {
    return () => {
      window.sessionStorage.removeItem('selected-employees')
      window.sessionStorage.removeItem('eb-selected-employees-proposed-product-id')
      window.sessionStorage.removeItem('eb-selected-employees-proposed-plans')
    }
  }, [])

  return (
    <Container>
      <div className='back-btn-container'>
        <Button
          onClick={() => history.push(`/employee-benefits/company-list/${match.params.companyId}/participants-list`)}
        >
          <Icon type='arrow-left' /> Back
        </Button>
      </div>
      <div className='content'>
        <CreatePaymentForm />
      </div>
    </Container>
  )
}
export default AddParticipantsPayment
