import ebUrls from '../../../../../request/urls/employeeBenefit'

export const PRODUCTS_ACTION = {
}

export const PARTICIPANTS_ACTIONS = {
  CREATE_PAYMENT_REQUEST: 'CREATE_PAYMENT_REQUEST',
  CREATE_PAYMENT: 'CREATE_PAYMENT',
  PRODUCT_PLANS_REQUEST: 'PRODUCT_PLANS_REQUEST',
  PRODUCT_PLANS: 'PRODUCT_PLANS',
  COMPANY_PACKAGE_REQUEST: 'COMPANY_PACKAGE_REQUEST',
  COMPANY_PACKAGE: 'COMPANY_PACKAGE',

  createPayment: payload => ({
    type: PARTICIPANTS_ACTIONS.CREATE_PAYMENT_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.createPaymentV2
    }
  }),
  getProductPlans: payload => ({
    type: PARTICIPANTS_ACTIONS.PRODUCT_PLANS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getProductPlans
    }
  }),
  getCompanyPackages: (payload) => (
    {
      type: PARTICIPANTS_ACTIONS.COMPANY_PACKAGE_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.companyPackages
      }
    }
  )
}
