import React, { useMemo } from 'react'
import { Table } from 'antd'
import { employeeMapperColumns } from './utility'

const EmployeeMapper = ({
  plansData,
  selectedUsers = [],
  benefitGroupSlug,
  noPlanEmployeeIds,
  productId,
  getFieldDecorator,
  ...props
}) => {
  const columns = useMemo(() => {
    return employeeMapperColumns({
      plansData,
      benefitGroupSlug,
      productId,
      noPlanEmployeeIds,
      getFieldDecorator
    })
  }, [plansData, benefitGroupSlug, productId, noPlanEmployeeIds, getFieldDecorator])
  return (
    <>
      <Table
        rowKey={rowData => rowData.planIdentifier}
        columns={columns}
        dataSource={selectedUsers}
        bordered
        size='small'
      />
    </>
  )
}
export default EmployeeMapper
