import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useEBContextValue } from '../../../context'
import { PARTICIPANTS_ACTIONS } from '../actions'

export const useParticipantsContext = () => {
  const [{ createPaymentData, productPlansData }, dispatch] = useEBContextValue()

  const [callApi] = useServiceRequest(dispatch)
  const createPaymentRequest = useCallback((payload = {}) => {
    callApi(PARTICIPANTS_ACTIONS.createPayment({ body: payload }))
  }, [callApi])

  const getProductPlans = useCallback((payload = {}) => {
    callApi(PARTICIPANTS_ACTIONS.getProductPlans({ query: payload }))
  }, [callApi])

  return {
    createPaymentRequest,
    createPaymentData,
    getProductPlans,
    productPlansData
  }
}

export const useCompanyPackages = () => {
  const [{ companyPackageData, companyPackageStatus }, dispatch] = useEBContextValue()
  //  follow this
  const [callApi] = useServiceRequest(dispatch)
  const request = useCallback((payload = {}) => {
    callApi(PARTICIPANTS_ACTIONS.getCompanyPackages(payload))
  }, [callApi])
  return [{ companyPackageData, companyPackageStatus }, request]
}
