import React, { useEffect, useState, useCallback, useMemo, useRef } from 'react'
import {
  Form,
  Col,
  Select,
  Spin,
  Alert,
  Button,
  message
} from 'antd'
import {
  useLoaderContextValue,
  useErrorContextValue,
  useResetError,
  usePost
} from '@pasarpolis/common-react-hooks'
import { RowWithMargin } from '../../../CommonComponents'
import { useHistory, useParams } from 'react-router'
import { useError } from '../../../../../../state/error/hooks/useError'
import { clearSessionStorageKeys, getFromSessionStorage } from '../../../../../../helpers/utility'
import { useCompanyPackages, useParticipantsContext } from '../../../state/ParticipantsPayment/hooks/useParticipantsContext'
import { getPlansAndTsiData, amountValidationRules, packageConfig, getSelectedUsersAndDependentsList } from './utility'
import EmployeeMapper from './employeeMapper'
import CustomNumberFormat from '../../../CommonComponents/CustomNumberFormat'
import { FILL_DATA_MODE } from './constants'
import { PlanMapperContainerStyleWrapper } from './index.style'
import ExcelUpload from './components/ExcelUpload'
import { participantApiConfig } from '../apiConfig'

const { Option } = Select
const { Item } = Form

const formItemLayout = {
  labelCol: { span: 8 },
  wrapperCol: { span: 16 }
}
const CreatePaymentForm = Form.create({ name: 'create_payment_form' })(({ ...props }) => {
  const { form } = props
  const { setFields, getFieldsValue, resetFields, validateFields, setFieldsValue } = form
  const [{ companyPackageData }, getCompanyPackages] = useCompanyPackages()
  const { createPaymentRequest, getProductPlans, productPlansData } = useParticipantsContext()
  const [paymentWithFileData, paymentWithFileRequest] = usePost(participantApiConfig.createPaymentWithFile)
  const proposedPlans = useMemo(() => getFromSessionStorage('eb-selected-employees-proposed-plans'), [])
  const proposedProductId = useMemo(() => window.sessionStorage.getItem('eb-selected-employees-proposed-product-id'), [])
  const selectedParticipants = useMemo(() => getFromSessionStorage('selected-employees') || [], [])
  const selectedParticipantsWithDependents = useMemo(() => getSelectedUsersAndDependentsList(selectedParticipants), [selectedParticipants])
  const [fillDataMode] = useState(selectedParticipants?.length ? FILL_DATA_MODE.MANUAL : FILL_DATA_MODE.FILE)
  const isProposedPlansSet = useRef(false)
  const [{
    CREATE_PAYMENT_ERROR,
    createPaymentErrorData,
    createPaymentStatus,
    companyPackageStatus,
    createPaymentStatusCode,
    productPlansStatus,
    PRODUCT_PLANS_ERROR,
    COMPANY_PACKAGE_ERROR,
    paymentByFileStatus,
    PAYMENT_BY_FILE_ERROR
  }] = useErrorContextValue()
  const [{
    CREATE_PAYMENT_LOADER,
    PRODUCT_PLANS_LOADER,
    COMPANY_PACKAGE_LOADER,
    PAYMENT_BY_FILE_LOADER
  }] = useLoaderContextValue()
  const { getFieldDecorator } = props.form
  const params = useParams()
  const { companyId } = params
  const { resetError } = useError()
  const productId = form.getFieldValue('product_id')
  const history = useHistory()
  const { resetError: resetErrorCommonHooks } = useResetError()
  const [noPlanEmployeeIds, setNoPlanEmployeeIds] = useState([])
  const values = getFieldsValue()

  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    validateFields((err, values) => {
      if (!err) {
        const clonedValues = {
          ...values,
          amount: String(values.amount || '').replace(/\./g, '').replace(',', '.')
        }
        const { participant_plan_mappings: participantPlanMappings, url: file, ...toBeSentValues } = clonedValues
        let planMappings
        if (participantPlanMappings) {
          planMappings = Object.fromEntries(Object.entries(participantPlanMappings))
        }
        if (fillDataMode === FILL_DATA_MODE.FILE) {
          const url = Array.isArray(file) && file.length === 1 ? file[0].url : ''
          if (url) {
            const toBeSentValuesWithFile = { ...toBeSentValues, url }
            paymentWithFileRequest(toBeSentValuesWithFile)
          } else {
            message.error('No files selected')
          }
        } else {
          createPaymentRequest({ ...toBeSentValues, participant_plan_mappings: planMappings })
        }
        resetErrorCommonHooks([
          'createPaymentStatus',
          'CREATE_PAYMENT_ERROR'
        ])
      }
    })
  }, [createPaymentRequest, resetErrorCommonHooks, validateFields, fillDataMode, paymentWithFileRequest])

  useEffect(() => {
    if (CREATE_PAYMENT_ERROR && createPaymentErrorData) {
      const { error, message: errorMessage } = createPaymentErrorData
      if (errorMessage) {
        message.error(errorMessage)
      }
      if (error) {
        const values = getFieldsValue()
        const fieldKeys = ['amount', 'url']
        for (const key of fieldKeys) {
          if (error[key]) {
            setFields({
              [key]: {
                value: values[key],
                errors: Array.isArray(error[key]) ? error[key].map(err => new Error(err)) : []
              }
            })
          }
        }
      }
    }
  }, [
    createPaymentErrorData,
    CREATE_PAYMENT_ERROR,
    setFields,
    getFieldsValue
  ])

  useEffect(() => {
    if (values.participant_plan_mappings && productId) {
      const planMappings = Object.fromEntries(Object.entries(values.participant_plan_mappings))
      for (const employeeId in planMappings) {
        let isAnyPlanPresent = false
        for (const benefitGroup in planMappings[employeeId]) {
          if (planMappings[employeeId][benefitGroup]) {
            isAnyPlanPresent = true
            break
          }
        }
        if (!isAnyPlanPresent) {
          if (!noPlanEmployeeIds.includes(employeeId)) {
            setNoPlanEmployeeIds(ids => [...ids, employeeId])
          }
        } else {
          if (noPlanEmployeeIds.includes(employeeId)) {
            setNoPlanEmployeeIds(ids => ids.filter(id => id !== employeeId))
          }
        }
      }
    }
  }, [values, noPlanEmployeeIds, productId])

  const { plansData, benefitGroupSlug } = getPlansAndTsiData(productPlansData)

  useEffect(() => {
    if (productPlansStatus === 'success') {
      const planMappings = proposedPlans?.participant_plan_mappings
      if (planMappings && !isProposedPlansSet.current) {
        isProposedPlansSet.current = true
        for (const key in planMappings) {
          for (const benefitGroup in planMappings[key]) {
            setFieldsValue({
              [`participant_plan_mappings.${key}.${benefitGroup}`]: planMappings[key][benefitGroup].id
            })
          }
        }
      }
    }
  }, [
    proposedPlans,
    productPlansStatus,
    setFieldsValue
  ])

  useEffect(() => {
    if (productId) {
      resetFields('participant_plan_mappings')
      getProductPlans({ product_id: productId })
    }
  }, [productId, getProductPlans, resetFields])

  useEffect(() => {
    if (createPaymentStatus === 'success') {
      message.success('Payment done successfully')
      clearSessionStorageKeys(['selected-employees'])
      history.push(`/employee-benefits/company-list/${params.companyId}/`)
    }
  }, [createPaymentStatus, history, params.companyId])

  useEffect(() => {
    if (paymentByFileStatus === 'success' && paymentWithFileData?.message) {
      message.success(paymentWithFileData.message)
      history.push(`/employee-benefits/company-list/${params.companyId}/`)
    }
  }, [paymentByFileStatus, paymentWithFileData, history, params.companyId])

  useEffect(() => {
    getCompanyPackages({ query: { company_id: companyId } })
    if (proposedProductId) {
      setFieldsValue({ product_id: proposedProductId })
    }
    return () => {
      resetError([
        'COMPANY_PACKAGE_ERROR',
        'companyPackageStatus',
        'productPlansStatus'
      ])
      resetErrorCommonHooks([
        'createPaymentStatus',
        'CREATE_PAYMENT_ERROR',
        'paymentByFileStatus',
        'PAYMENT_BY_FILE_ERROR',
        'productPlansStatus'
      ])
    }
  }, [
    getCompanyPackages,
    companyId,
    resetError,
    resetErrorCommonHooks,
    setFieldsValue,
    selectedParticipantsWithDependents,
    proposedProductId
  ])

  return (
    <Spin spinning={!!CREATE_PAYMENT_LOADER || !!COMPANY_PACKAGE_LOADER || !!PAYMENT_BY_FILE_LOADER}>
      {CREATE_PAYMENT_ERROR && createPaymentStatusCode !== 400 && <Alert type='error' message={createPaymentStatus} banner />}
      {COMPANY_PACKAGE_ERROR && <Alert type='error' message={companyPackageStatus} banner />}
      {PRODUCT_PLANS_ERROR && <Alert type='error' message={productPlansStatus} banner />}
      {PAYMENT_BY_FILE_ERROR && <Alert type='error' message={paymentByFileStatus} banner />}
      <h2>Creating Payment</h2>
      <Form>
        <RowWithMargin gutter={16}>
          <Col span={12}>
            <Item
              hasFeedback
              label='Product'
              {...formItemLayout}
              labelAlign='left'
            >
              {
                getFieldDecorator('product_id', packageConfig)(
                  <Select
                    style={{ width: '100%' }}
                  >
                    {companyPackageData && companyPackageData.data
                      ? companyPackageData.data.map(item => (
                        <Option
                          key={item._packageID}
                          value={item._packageID}
                        >
                          {item._packageID}
                        </Option>
                        ))
                      : null}
                  </Select>
                )
              }
            </Item>
          </Col>
          <Col span={12}>
            <Form.Item
              hasFeedback
              label='Amount'
              {...formItemLayout}
              labelAlign='left'
            >
              {
                getFieldDecorator('amount', {
                  validateTrigger: ['onBlur'],
                  rules: amountValidationRules
                })(
                  <CustomNumberFormat />
                )
              }
            </Form.Item>
          </Col>
        </RowWithMargin>
        <Spin spinning={!!PRODUCT_PLANS_LOADER}>
          <RowWithMargin>
            <Col><h3>Plans Mapping</h3></Col>
          </RowWithMargin>
          {
            !!productId && fillDataMode === FILL_DATA_MODE.FILE && (
              <ExcelUpload
                form={form}
                productId={productId}
                getFieldDecorator={getFieldDecorator}
              />
            )
          }
          <PlanMapperContainerStyleWrapper>
            {
              !!productId && fillDataMode === FILL_DATA_MODE.MANUAL && plansData && benefitGroupSlug && (
                <EmployeeMapper
                  plansData={plansData}
                  form={form}
                  selectedUsers={selectedParticipantsWithDependents}
                  benefitGroupSlug={benefitGroupSlug}
                  productId={productId}
                  noPlanEmployeeIds={noPlanEmployeeIds}
                  getFieldDecorator={getFieldDecorator}
                />
              )
            }
            {
              !!productId && (
                <RowWithMargin type='flex' justify='end'>
                  <Button
                    type='primary'
                    onClick={handleSubmit}
                    disabled={noPlanEmployeeIds.length}
                  >
                    Submit
                  </Button>
                </RowWithMargin>
              )
            }
          </PlanMapperContainerStyleWrapper>
        </Spin>
      </Form>

    </Spin>
  )
})

export default CreatePaymentForm
