import { PARTICIPANTS_ACTIONS } from './actions'

const reducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case PARTICIPANTS_ACTIONS.CREATE_PAYMENT:
    case PARTICIPANTS_ACTIONS.PRODUCT_PLANS:
    case PARTICIPANTS_ACTIONS.COMPANY_PACKAGE:
      return { ...state, ...payload }
    default:
      return state
  }
}

export default reducer
