import axios from 'axios'
import querySearchBuilder from '../../helpers/querySearchBuilder'
import makeFileUrlPublicCall from './makeFileUrlPublic'
import { getHeader } from '../../helpers/utility'
import urlMapper from '../../helpers/urlMapper'

const uploadFileOnGcsV2Request = ({
  signedUrl = '',
  query = {},
  body = {},
  params = {},
  signedUrlBody = {},
  makeFileUrlPublic = false,
}) => {
  const queryString = querySearchBuilder(query)
  const mappedUrlSigned = urlMapper(signedUrl, params)
  const combinedSignedUrl = `${mappedUrlSigned}${queryString}`
  return axios
    .post(combinedSignedUrl, signedUrlBody, { headers: getHeader() })
    .then(response => {
      const { data } = response
      return axios.put(data.signed_url, body.file, { headers: { 'Content-type': body.file.type } })
        .then(res => {
          res.data = { 
            url: data.url,
            filename: data.filename
           }
          return res
        }).then(res =>{
          if(makeFileUrlPublic){
            makeFileUrlPublicCall({
              fileList: [res?.data?.filename]
            })
          }
          return res
        })
        // .catch(err => {
        //   err.data = {}
        //   throw err
        // })
    })
    // .catch(error => {
    //   error.data = {}
    //   if (error.response) {
    //     throw error
    //   } else {
    //     throw error
    //   }
    // })
}
export default uploadFileOnGcsV2Request
